// The Idle Adventure's Town Map (README: Idle Adventure, Town Map; the user's): FireRed's Kanto map, its places the run's
// towns, routes and dungeons, generated by tools/idle/town_map.py (data/gen1/town-map.ts). A town is travelled to
// (TRAVEL); a route or dungeon takes a Wild or Trainer grind (GRIND_AT); only those the run has reached.
import { areas, areaIndex, areaOpen, isTown, mapView } from './areas.js';
import { generation, perGeneration, type Generation } from './generation.js';
import { wildSpots } from './idle.js';
import type { EncounterTable } from './types.js';

/** The active generation's Town Map picture and its grid (Generation.townMapGrid). */
export const townMapGrid = () => generation().townMapGrid;

export interface TownMapPlace {
  /** Its map section (MAPSEC_, lower case). */
  section: string;
  /** Its name as the game's map shows it. */
  name: string;
  /** The run's areas there (areas()' ids): a town's every visit (Viridian City's two), a route's or dungeon's one. */
  areas: string[];
  /** Its cells on the grid, on the map's layer or the dungeons' (a dungeon's cell over a route's: the dungeon's first). */
  cells: [x: number, y: number, layer: 'map' | 'dungeon'][];
}

export const townMapPlaces = (): readonly TownMapPlace[] => generation().townMapPlaces;

/** The place at a grid cell, the dungeons' layer first, or null. */
export function townMapPlaceAt(x: number, y: number): TownMapPlace | null {
  const at = (layer: 'map' | 'dungeon') => townMapPlaces().find((p) => p.cells.some(([cx, cy, l]) => cx === x && cy === y && l === layer));
  return at('dungeon') ?? at('map') ?? null;
}

/**
 * The area a place stands for in a run that has reached `reached` (areas()' index): a town's latest visit reached (Viridian
 * City with its gym once there), a route's or dungeon's own (one off the main road once its `opens` is reached; a
 * main-road route's first, Route 21's before its tall grass: townMapAreas has both); null when none is reached yet.
 */
export function townMapArea(place: TownMapPlace, reached: number): number | null {
  const indices = townMapAreas(place, reached);
  if (!indices.length) return null;
  return isTown(areas()[indices[0]!]!) ? indices[indices.length - 1]! : indices[0]!;
}

/** Every area of a place a run that has reached `reached` can go to (a route's grinds are offered in each: Route 21's and its tall grass's). */
export function townMapAreas(place: TownMapPlace, reached: number): number[] {
  return place.areas.map(areaIndex).filter((i) => i >= 0 && areaOpen(i, reached));
}

/**
 * The place an area is on (a gym or a League room: its town's; grinding from a town: the town's); with the map the run
 * is on, the place of that map's section among the area's (Route 17 of Routes 16, 17 and 18).
 */
export function townMapPlaceOf(index: number, map?: string): TownMapPlace | null {
  let a = areas()[index];
  if (!a) return null;
  if (a.kind === 'gym' && a.town) a = areas()[areaIndex(a.town)]!;
  if (a.kind === 'league') a = areas().find((t) => isTown(t) && t.id === generation().league.town) ?? a;
  const id = a.id;
  const section = map && mapView(map).section;
  return (section && townMapPlaces().find((p) => p.areas.includes(id) && p.section === section)) || (townMapPlaces().find((p) => p.areas.includes(id)) ?? null);
}

/**
 * A species' habitat on the Town Map (the Pokédex entry's Area, as the games' Pokédex shows it: the user's, 2026-11-06):
 * the places whose maps' wild tables have it (walked, surfed, fished, Rock Smash; the morning's, the night's, LeafGreen's
 * and SoulSilver's slots, and the extra slots of the gifts, trades and prizes, firered_data.py's), only the tables a grind
 * can reach (wildSpots: Mt. Moon's B2F, which no track walks, left out, the user's, 2026-11-22), and the place of a
 * legendary Pokémon's area (WalkArea.legend). The active generation's; none where it has no wild Pokémon of it.
 */
export const habitat = (species: number): readonly TownMapPlace[] => habitats().get(species) ?? [];

/**
 * A species' habitat as the Pokédex entry writes it (the user's, 2026-11-20): each place, and where it has several zones
 * with wild Pokémon (Mt. Moon's floors, the Safari Zone's areas), the zones it's found in ("SAFARI ZONE: Center, East").
 */
export const habitatText = (species: number): string[] =>
  habitat(species).map((place) => {
    const zones = habitatZones().get(species)?.get(place.section) ?? [];
    const all = zoneMaps().get(place.section) ?? [];
    return all.length > 1 && zones.length ? `${place.name}: ${zones.map((m) => zoneLabel(m, place.name)).filter((z, i, l) => l.indexOf(z) === i).join(', ')}` : place.name;
  });

/**
 * A zone's name in its place: the map's name less the place's ("SafariZone_Center" Center, "MtMoon_B1F" B1F, Johto's
 * "IcePathB1f" B1F, "MeteorFalls_B1F_1R" B1F 1R), words split and floors in capitals.
 */
export function zoneLabel(map: string, placeName: string): string {
  const words = (s: string) => s.replace(/([a-z])([A-Z0-9])/g, '$1 $2').replace(/([0-9])([A-Z][a-z])/g, '$1 $2').split(/[\s_]+/).filter(Boolean);
  const place = words(placeName.replace(/[^A-Za-z0-9 ]/g, '')).map((w) => w.toLowerCase());
  const rest = map.includes('_') ? words(map.slice(map.indexOf('_') + 1)) : words(map);
  // Johto's names start with their place's (Ice Path's): those words left out.
  let i = 0;
  while (i < rest.length && i < place.length && rest[i]!.toLowerCase().replace(/[^a-z0-9]/g, '') === place[i]!.replace(/[^a-z0-9]/g, '')) i++;
  return (rest.slice(i).join(' ') || map).replace(/\b(B?\d+)f\b/g, '$1F');
}

/** Each place's maps with wild Pokémon, by section (zoneLabel's zones). */
const zoneMaps = perGeneration((g) => {
  const out = new Map<string, string[]>();
  for (const [name, map] of Object.entries(g.maps)) if (map.section && reachable().has(name)) (out.get(map.section) ?? out.set(map.section, []).get(map.section)!).push(name);
  return out;
});

/** The kinds of wild table ('l' walked, 'w' surfed, 'f' fished) a grind can reach on each map: every area's wildSpots. */
const reachable = perGeneration((g: Generation) => {
  const out = new Map<string, Set<string>>();
  g.areas.forEach((_, i) => {
    for (const spot of wildSpots(i)) (out.get(spot.map) ?? out.set(spot.map, new Set()).get(spot.map)!).add(spot.id.slice(spot.id.lastIndexOf(':') + 1));
  });
  return out;
});

/** Each species' maps by section (habitats' wild tables, map by map). */
const habitatZones = perGeneration((g) => {
  const out = new Map<number, Map<string, string[]>>();
  for (const [name, map] of Object.entries(g.maps)) {
    const table = g.encounters[map.encounters];
    const kinds = reachable().get(name);
    if (!table || !map.section || !kinds) continue;
    for (const s of tableSpecies(table, kinds)) {
      const bySection = out.get(s) ?? out.set(s, new Map()).get(s)!;
      const maps = bySection.get(map.section) ?? bySection.set(map.section, []).get(map.section)!;
      if (!maps.includes(name)) maps.push(name);
    }
  }
  return out;
});

/**
 * Every species a wild table can give in the kinds a grind reaches there (reachable: walked with Rock Smash, surfed,
 * fished; mornings', nights', LeafGreen's and SoulSilver's slots, extra slots).
 */
function tableSpecies(table: EncounterTable, kinds: Set<string>): Set<number> {
  const out = new Set<number>();
  const lists = { l: [table.land, table.rockSmash], w: [table.water], f: [table.fishing, table.oldRod, table.goodRod, table.superRod] };
  for (const slots of (['l', 'w', 'f'] as const).flatMap((k) => (kinds.has(k) ? lists[k] : []))) {
    if (!slots) continue;
    for (const list of [slots.mons, slots.extra, slots.morning, slots.night]) for (const [, , s] of list ?? []) out.add(s);
    for (const list of [slots.leafGreen, slots.soulSilver?.morning, slots.soulSilver?.day, slots.soulSilver?.night]) for (const [, , , s] of list ?? []) out.add(s);
  }
  if (table.nightFish && kinds.has('f')) out.add(table.nightFish);
  return out;
}

const habitats = perGeneration((g) => {
  const sections = new Map<number, Set<string>>();
  const add = (species: number, section: string) => (sections.get(species) ?? sections.set(species, new Set()).get(species)!).add(section);
  for (const [name, map] of Object.entries(g.maps)) {
    const table = g.encounters[map.encounters];
    const kinds = reachable().get(name);
    if (!table || !map.section || !kinds) continue;
    for (const s of tableSpecies(table, kinds)) add(s, map.section);
  }
  const out = new Map<number, TownMapPlace[]>();
  for (const [species, found] of sections) out.set(species, g.townMapPlaces.filter((p) => found.has(p.section)));
  for (const a of g.areas) {
    const legend = 'legend' in a ? a.legend : undefined;
    const place = legend && g.townMapPlaces.find((p) => p.areas.includes(a.id));
    if (!legend || !place) continue;
    const list = out.get(legend.species) ?? out.set(legend.species, []).get(legend.species)!;
    if (!list.includes(place)) list.push(place);
  }
  return out;
});
